fn solve(a: i8, b: i8, c: i8) -> i8 {
    let mut nums = [a, b, c];
    nums.sort_unstable();

    let [x, y, z] = nums;

    // If all are already equal
    if x == y && y == z {
        return 0;
    }

    // Try to reach a common target value
    // Since operations can only increase numbers, the target must be >= z (largest)
    // We try targets from z up to some reasonable limit (z + 4 is enough given constraints)
    let mut best = i8::MAX;

    for target in z..=z + 4 {
        let mut ops = 0;
        let mut remaining = [target - x, target - y, target - z];

        // All differences must be non-negative
        if remaining.iter().any(|&diff| diff < 0) {
            continue;
        }

        // Pair as many +1/+1 operations as possible
        for diff in remaining.iter_mut() {
            // Use +2 operations for odd differences
            if *diff % 2 == 1 {
                ops += 1;
                *diff -= 1;
            }
        }

        // Now all diffs are even
        let total_remaining: i8 = remaining.iter().sum();
        ops += total_remaining / 2;

        // Check if this ops count is achievable
        // Each +2 operation handles 2 units, each +1/+1 operation handles 2 units total
        // So total units to cover must be even? Let's verify:
        // Actually, total_remaining is even now because we made all diffs even.
        // Each +2 operation covers 2 units (counts as 1 op).
        // Each +1/+1 operation covers 2 units total (counts as 1 op).
        // So ops = total_remaining / 2 is correct.

        best = best.min(ops);
    }

    best
}